package br.com.equilibra.transaction.api;
import br.com.equilibra.transaction.domain.*; import java.math.BigDecimal; import java.time.Instant;
public record TransactionHistoryResponse(String id,TransactionType type,TransactionStatus status,String description,Instant occurredAt,BigDecimal amount,String categoryId,String sourceAccountId,String destinationAccountId,String notes,Instant createdAt,Instant updatedAt,java.util.List<TagSummary> tags,long attachmentCount){public static TransactionHistoryResponse from(FinancialTransaction t){return from(t,java.util.List.of(),0);}public static TransactionHistoryResponse from(FinancialTransaction t,java.util.List<TagSummary> tags,long attachmentCount){return new TransactionHistoryResponse(t.getId(),t.getType(),t.getStatus(),t.getDescription(),t.getOccurredAt(),t.getAmount(),t.getCategoryId(),t.getSourceAccountId(),t.getDestinationAccountId(),t.getNotes(),t.getCreatedAt(),t.getUpdatedAt(),tags,attachmentCount);}}
